import urllib.request
url='http://deps.buildcache.dev/setup-guide'
try:
    text=urllib.request.urlopen(url, timeout=10).read().decode()
except Exception as e:
    print(f'fetch failed: {type(e).__name__}: {e}')
    raise SystemExit(1)
print('--- troubleshooting matches ---')
lines=text.splitlines()
in_trouble=False
for i,line in enumerate(lines,1):
    if line.strip().lower().startswith('## 6. troubleshooting'):
        in_trouble=True
    elif in_trouble and line.strip().startswith('## '):
        break
    elif in_trouble:
        print(f'{i}: {line}')
print('--- lockfile/stale matches ---')
for i,line in enumerate(lines,1):
    if any(term in line.lower() for term in ('lock', 'stale', 'old checkout', 'venv')):
        print(f'{i}: {line}')
PY
